class ResourceManager{constructor(e,t,r){this.character=e,this.resourceType=t,this.maxResource=r,this.currentResource=0,this.resourceRegen=0,this.timer=0,this.lastCastTime=0,this.inFiveSecondRule=!1}addResource(e,t="unknown"){const r=this.currentResource;return this.currentResource=Math.min(this.currentResource+e,this.maxResource),this.character.logging&&this.character.log(`Resource ${this.resourceType}: ${r.toFixed(1)} + ${e.toFixed(1)} = ${this.currentResource.toFixed(1)} (${t})`),this.currentResource}spendResource(e,t="unknown"){if(this.currentResource<e)return!1;const r=this.currentResource;return this.currentResource-=e,this.character.logging&&this.character.log(`Spent ${e} ${this.resourceType} on ${t}: ${r.toFixed(1)} -> ${this.currentResource.toFixed(1)}`),"Mana"===this.resourceType&&(this.lastCastTime=step,this.inFiveSecondRule=!0),!0}stepRegen(e){switch(this.resourceType){case"Energy":this.stepEnergyRegen(e);break;case"Mana":this.stepManaRegen(e);break;case"Rage":this.stepRageDecay(e)}}stepEnergyRegen(e){this.timer+=e,this.timer>=2e3&&(this.addResource(20,"energy regen"),this.timer-=2e3)}stepManaRegen(e){if(this.inFiveSecondRule&&step-this.lastCastTime>=5e3&&(this.inFiveSecondRule=!1),!this.inFiveSecondRule&&(this.timer+=e,this.timer>=2e3)){const e=(this.character.stats.mp5||0)/5*2+this.calculateSpiritRegen();this.addResource(e,"mana regen"),this.timer-=2e3}}calculateSpiritRegen(){return.001*((this.character.stats.spi||0)/5+15)*(this.character.stats.int||0)*5}stepRageDecay(e){this.timer+=e,this.timer>=3e3&&(this.currentResource>0&&(this.currentResource=Math.max(0,this.currentResource-1)),this.timer-=3e3)}addRageFromDamage(e,t=!1){if("Rage"!==this.resourceType)return;const r=this.character.rageconversion||230.6;let s;s=t?e/r*2.5:e/r*7.5,s*=this.character.ragemod||1,this.addResource(s,t?"damage taken":"damage dealt")}hasResource(e){return this.currentResource>=e}getResource(){return this.currentResource}setResource(e){this.currentResource=Math.max(0,Math.min(e,this.maxResource))}getResourcePercent(){return this.currentResource/this.maxResource*100}}